def canMakeEqual(nums, k):
    n = len(nums)

    def flips_needed(target):
        arr = nums[:]
        count = 0
        for i in range(n - 1):
            if arr[i] != target:
                arr[i] *= -1
                arr[i + 1] *= -1
                count += 1
        # the last element cannot be fixed by a later step
        if arr[n - 1] != target:
            return float('inf')
        return count

    return min(flips_needed(1), flips_needed(-1)) <= k
